CREATE TABLE IF NOT EXISTS `annonces` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `utilisateur_id` INT NOT NULL,
  `type_annonce` ENUM('offre', 'demande') NOT NULL, -- 'offre' pour les mentors, 'demande' pour les étudiants
  `matiere` VARCHAR(100) NOT NULL,                  -- Ex: Mathématiques, Python, Réseaux
  `horaires` VARCHAR(255) NOT NULL,                 -- Ex: Samedi matin, Soirée en semaine
  `format` ENUM('présentiel', 'en ligne', 'hybride') NOT NULL,
  `description` TEXT,
  `date_publication` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`utilisateur_id`) REFERENCES `utilisateurs`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


